/* ============================================================================
   Yume Forge — "final-fantasy-gemini"

   The Final Fantasy theme, ported to gemini.google.com. Same love letter —
   royal blue menu windows, hard white frames, gold cursor, the crystal beside
   every reply, the party idling on the composer — reseated on Gemini's DOM.

   Written against the live signed-in Pro build (2026-08-11): the app is
   Angular + Material, so surfaces hang off --gem-sys-color--* / --bard-color-*
   custom properties (finished colours, not triplets), turns are
   .conversation-container holding <user-query> (bubble:
   .user-query-bubble-with-background) and <model-response> (body:
   message-content .markdown; actions: <message-actions>; reasoning:
   model-thoughts / .thoughts-container). The composer is <input-container> >
   fieldset.input-area-container > <input-area-v2> around a Quill
   <rich-textarea> (.ql-editor). Sidebar rows are <gem-nav-list-item> keyed by
   their link hrefs; icons everywhere are <mat-icon> font ligatures
   (lumi-symbols / Google Symbols), so icon swaps hide the glyph text and draw
   a sprite on the slot. Busy is stamped by content.js as data-yume-working on
   the newest model-response (stop affordance + pending markers, with
   hysteresis), the same contract as the ChatGPT theme.

   Covers both the Chat surface and the Spark tab: Spark reuses the same
   chat-window / input-area-v2 / conversation-container machinery, so every
   rule below that keys on those elements applies there unchanged.

   This file is SELF-CONTAINED on purpose: _base.css is claude-only, so the
   ambience scaffolding (html::before/::after, the starfield pseudos, the fall
   keyframes) is declared here. Shares the generated sprite sheets and fonts
   with the other themes via the same manifest css list.
   ========================================================================== */

__YUME_ROOT__ {
  /* --- window frame ------------------------------------------------------ */
  --ff-win-top: #2f47a8;
  --ff-win-mid: #16225e;
  --ff-win-bot: #0b1240;
  --ff-frame: #ffffff;
  --ff-bevel: rgba(148, 176, 244, 0.55);
  --ff-drop: rgba(3, 6, 22, 0.72);

  --ff-gold: #ffd75e;
  --ff-crystal-cyan: #8beaff;

  --ff-window: linear-gradient(180deg, var(--ff-win-top) 0%, var(--ff-win-mid) 58%, var(--ff-win-bot) 100%);
  --ff-window-user: linear-gradient(180deg, #3a55c4 0%, #1e2e78 58%, #12194f 100%);
  --ff-window-reply: linear-gradient(180deg, #1a2568 0%, #0e1442 60%, #070b2a 100%);
  --ff-frame-shadow:
    inset 0 0 0 1px var(--ff-bevel),
    0 3px 0 var(--ff-drop),
    0 8px 22px rgba(0, 0, 0, 0.45);

  /* --- type -------------------------------------------------------------- */
  --ff-pixel: "Yume Press Start", ui-monospace, monospace;
  --ff-pixel-ui: "Yume Silkscreen", "Yume Press Start", ui-monospace, monospace;
  --ff-body: var(--ff-pixel);
  --ff-mono: ui-monospace, SFMono-Regular, "SF Mono", Menlo, Consolas, monospace;
}

/* ---------------------------------------------------------------- tokens */

/* Gemini paints nearly everything through Material/system design tokens
   holding finished colours. The page-wide surfaces go TRANSPARENT so the
   body's sky gradient (below) shows through everywhere; anything that
   genuinely needs its own panel (menus, dialogs, bubbles, composer) is
   explicitly dressed as a menu window further down. */
__YUME_ROOT__,
__YUME_ROOT__ body,
__YUME_ROOT__ body * {
  /* System surface ramp: main canvases transparent, elevated panels navy. */
  --gem-sys-color--surface: transparent !important;
  --gem-sys-color--surface-dim: transparent !important;
  --gem-sys-color--surface-bright: #1d2a75 !important;
  --gem-sys-color--surface-container-lowest: rgba(7, 11, 42, 0.6) !important;
  --gem-sys-color--surface-container-low: #131c58 !important;
  --gem-sys-color--surface-container: #16205e !important;
  --gem-sys-color--surface-container-high: #1a2568 !important;
  --gem-sys-color--surface-container-highest: #1d2a75 !important;
  --gem-sys-color--surface-variant: #1d2a75 !important;

  --gem-sys-color--on-surface: #ffffff !important;
  --gem-sys-color--on-surface-variant: #dbe4ff !important;
  --gem-sys-color--on-surface-low: #a9b7e8 !important;

  --gem-sys-color--outline: rgba(255, 255, 255, 0.55) !important;
  --gem-sys-color--outline-variant: rgba(255, 255, 255, 0.3) !important;
  --gem-sys-color--outline-low: rgba(255, 255, 255, 0.26) !important;

  --gem-sys-color--primary: var(--ff-gold) !important;
  --gem-sys-color--on-primary: #241c04 !important;
  --gem-sys-color--primary-container: #1f2f78 !important;
  --gem-sys-color--on-primary-container: #dbe4ff !important;
  --gem-sys-color--secondary: #8beaff !important;
  --gem-sys-color--secondary-container: #14406e !important;
  --gem-sys-color--on-secondary-container: #c2e7ff !important;

  /* Legacy bard tokens the sidenav and composer still read. */
  --bard-color-sidenav-background-desktop: transparent !important;
  --bard-color-sidenav-background-mobile: #10184c !important;
  --bard-color-sidenav-scrim: rgba(4, 8, 30, 0.6) !important;
  --bard-color-main-container-background: transparent !important;
  --bard-color-chat-container-background: transparent !important;
  --bard-color-response-container-background: transparent !important;
  --bard-color-response-container-flipped-background: #16205e !important;
  --bard-color-input-area-background: transparent !important;
