  --bard-color-input-companion-button-active-background: rgba(255, 215, 94, 0.22) !important;
  --bard-color-input-area-buttons-hover-background: rgba(255, 215, 94, 0.16) !important;
  --bard-color-surface-tint: #8beaff !important;
  --bard-color-on-surface: #ffffff !important;
  --bard-color-on-surface-variant: #dbe4ff !important;

  /* Material component panels (menus, dialogs, selects, tooltips, cards). */
  --mat-menu-container-color: #131c58 !important;
  --mat-menu-item-label-text-color: #ffffff !important;
  --mat-menu-item-icon-color: #dbe4ff !important;
  --mat-dialog-container-color: #131c58 !important;
  --mat-select-panel-background-color: #131c58 !important;
  --mat-option-label-text-color: #ffffff !important;
  --mat-app-background-color: transparent !important;
  --mat-app-text-color: #ffffff !important;
  --mat-card-container-color: #131c58 !important;
  --mat-tooltip-container-color: #10184c !important;
  --mat-tooltip-supporting-text-color: #ffffff !important;
  --mat-sidenav-container-background-color: transparent !important;
  --mat-sidenav-content-background-color: transparent !important;
  --mat-sidenav-container-text-color: #ffffff !important;
  --mat-expansion-container-background-color: transparent !important;
  --mat-expansion-container-text-color: #ffffff !important;
  --mat-bottom-sheet-container-background-color: #131c58 !important;

  /* Text tokens Gemini components read directly. */
  --mat-slide-toggle-selected-track-color: var(--ff-gold) !important;
  --mat-icon-color: #dbe4ff !important;
}

/* -------------------------------------------------------------- ambience */

/* The sky. body carries the page gradient plus (optionally) the horizon
   silhouette; the page's own wrappers were made transparent above, so this is
   what shows behind every surface. Fixed attachment: the thread scroller is
   thousands of px tall and a scrolling gradient would stretch to nothing. */
__YUME_ROOT__ {
  --ff-horizon: none;
}
__YUME_ROOT__[data-yume-opt~="bottom-scenery"] {
  --ff-horizon: var(--yume-ff-silhouette);
}

__YUME_ROOT__ body {
  background-image: var(--ff-horizon), linear-gradient(180deg,
    hsl(226 62% 26%) 0%,
    hsl(230 64% 18%) 26%,
    hsl(233 66% 12%) 58%,
    hsl(234 66% 9%) 100%) !important;
  background-attachment: fixed, fixed !important;
  background-repeat: no-repeat, no-repeat !important;
  /* Art composed with its subjects at the right, so they never leave the
     screen; a wider window reveals more of the scene's left. Natural size. */
  background-position: right bottom, center !important;
  background-size:
    calc(var(--yume-ff-silhouette-w) * 1px) calc(var(--yume-ff-silhouette-h) * 1px),
    100% 100% !important;
  background-color: #0b1240 !important;
}

/* The app's own full-height wrappers go glass so the sky shows through.
   input-container gets extra selector weight and the longhand too: it ships
   an opaque #0f0f0f of its own that showed as a black band across the
   viewport bottom the moment a reply pushed the layout — the band is this
   element, not the collapsed toolbox drawer. */
__YUME_ROOT__ chat-app,
__YUME_ROOT__ main.chat-app,
__YUME_ROOT__ bard-sidenav-container,
__YUME_ROOT__ bard-sidenav-content,
__YUME_ROOT__ chat-window,
__YUME_ROOT__ chat-window-content,
__YUME_ROOT__ #chat-history,
__YUME_ROOT__ .chat-container,
__YUME_ROOT__ input-container,
__YUME_ROOT__ body input-container,
__YUME_ROOT__ chat-window input-container,
__YUME_ROOT__ input-container.hide-on-print {
  background: transparent !important;
  background-color: transparent !important;
}

/* Moon + corner washes, floating above the page (same layer budget as the
   claude theme: html::before is scenery, html::after is the falling motes,
   body::before/::after are the two starfields). All are pointer-events-none
   fixed layers, self-declared since _base.css does not load here. */
__YUME_ROOT__::before {
  content: "";
  position: fixed;
  inset: 0;
  pointer-events: none;
  z-index: 2147483645;
  background-image:
    var(--yume-ff-moon),
    radial-gradient(1100px 700px at 50% -14%, rgba(72, 116, 255, 0.16), transparent 72%),
    radial-gradient(900px 620px at -8% 108%, rgba(30, 58, 176, 0.12), transparent 74%);
  background-repeat: no-repeat, no-repeat, no-repeat;
  background-position:
    right clamp(10px, 3.4vw, 78px) top clamp(8px, 2.2vh, 34px),
    center, center;
  background-size: clamp(118px, 14vw, 208px), auto, auto;
}

@media (max-width: 560px) {
  __YUME_ROOT__::before { background-image: none, none, none; }
}

@keyframes cct-fall { from { transform: translateY(0); } to { transform: translateY(460px); } }

/* Crystal motes drifting down. */
__YUME_ROOT__::after {
  content: "";
  position: fixed;
  left: 0; right: 0; top: -460px; bottom: 0;
  pointer-events: none;
  z-index: 2147483646;
  will-change: transform;
  opacity: 0.75;
  background-repeat: repeat;
  background-image: var(--yume-ff-motes);
  animation: cct-fall 34s linear infinite;
}

@keyframes ff-twinkle {
  0%, 100% { opacity: 0.18; }
  38%      { opacity: 1; }
  64%      { opacity: 0.32; }
}

__YUME_ROOT__ body::before,
__YUME_ROOT__ body::after {
  content: "";
  position: fixed;
  left: 0; right: 0; top: -460px; bottom: 0;
  pointer-events: none;
  z-index: 2147483644;
  will-change: transform;
  background-repeat: repeat;
}

__YUME_ROOT__ body::before {
  background-image: var(--yume-ff-stars-far);
  opacity: 0.62;
  animation: cct-fall 72s linear infinite;
}

__YUME_ROOT__ body::after {
  background-image: var(--yume-ff-stars-near);
  animation:
    cct-fall 46s linear infinite,
    ff-twinkle 4.6s ease-in-out infinite;
}

/* Shooting stars — spawned by content.js, geometry per-star. */
__YUME_ROOT__ .yume-shooting-star {
  position: fixed;
  z-index: 2147483643;
  width: var(--len, 140px);
  height: 2px;
  border-radius: 2px;
  transform-origin: 0 50%;
  pointer-events: none;
  background: linear-gradient(90deg,
    rgba(180, 214, 255, 0) 0%,
    rgba(190, 224, 255, 0.55) 55%,
    rgba(236, 248, 255, 0.95) 88%,
    #ffffff 100%);
  filter: drop-shadow(0 0 6px rgba(150, 210, 255, 0.85));
  animation: yume-shoot var(--dur, 1.4s) cubic-bezier(0.25, 0.5, 0.5, 1) forwards;
}

@keyframes yume-shoot {
  0%   { transform: rotate(var(--ang, 30deg)) translateX(0); opacity: 0; }
  12%  { opacity: 1; }
  72%  { opacity: 1; }
  100% { transform: rotate(var(--ang, 30deg)) translateX(var(--travel, 100vw)); opacity: 0; }
}

/* ------------------------------------------------------------------ type */

/* Gemini sets families high up and sizes per element, so one body-level
   override carries the UI face everywhere; prose and code re-declare below.
   mat-icon is exempted right after — its "text" is a ligature glyph, and a
   pixel font on it would literally spell the icon's name. */
__YUME_ROOT__ body,
__YUME_ROOT__ button,
__YUME_ROOT__ input,
__YUME_ROOT__ select,
__YUME_ROOT__ textarea,
__YUME_ROOT__ kbd {
  font-family: var(--ff-pixel-ui) !important;
  letter-spacing: 0.01em;
}

__YUME_ROOT__ mat-icon,
__YUME_ROOT__ .lumi-symbols,
__YUME_ROOT__ .google-symbols,
__YUME_ROOT__ .material-symbols-outlined {
  font-family: "Luminous Symbols", "lumi-symbols", "Google Symbols", "Material Symbols Outlined", "Material Symbols Rounded" !important;
  letter-spacing: normal;
}

/* Message and composer text — Press Start 2P (real lowercase; Silkscreen's
   lowercase is bitmap-identical to caps and reads as SHOUTING).

   0.75rem = 12px, and both the unit and the number are load-bearing: REM
   because the list includes `*` and an em would compound per nesting level;
   12px because Press Start 2P sits on an 8px grid and is only crisp at whole
   device pixels per glyph pixel (on 2x: 12px = exactly 3). Adjust only in
   whole 4px steps. Colour stated EXPLICITLY — never inherited from the site's
   tokens (the friend-build lesson from claude.ai). */
__YUME_ROOT__ .markdown,
__YUME_ROOT__ .markdown :not(mat-icon):not(code):not(pre):not(pre *),
__YUME_ROOT__ user-query .query-text,
__YUME_ROOT__ user-query .query-text *,
__YUME_ROOT__ rich-textarea .ql-editor,
__YUME_ROOT__ rich-textarea .ql-editor :not(mat-icon) {
  font-family: var(--ff-body) !important;
  font-size: 0.75rem !important;
  line-height: 1.9 !important;
  letter-spacing: normal;
  color: #fff !important;
}

/* Code keeps a real monospace, inside prose and composer alike. */
__YUME_ROOT__ code,
__YUME_ROOT__ pre,
__YUME_ROOT__ pre *,
__YUME_ROOT__ code-block,
__YUME_ROOT__ code-block .code-container * {
  font-family: var(--ff-mono) !important;
}

/* Markdown headings inside replies: pixel with the classic hard shadow. */
__YUME_ROOT__ .markdown h1,
__YUME_ROOT__ .markdown h2,
__YUME_ROOT__ .markdown h3,
__YUME_ROOT__ .markdown h4 {
  font-family: var(--ff-pixel) !important;
  font-size: 0.875rem !important;   /* 14px — one step above body, still on grid at 2x */
  line-height: 1.8 !important;
  text-shadow: 2px 2px 0 rgba(3, 6, 22, 0.85);
  letter-spacing: 0.02em;
}

/* The zero-state greeting ("Your move, <name>!"): .zero-state-container >
   modular-zero-state > h1.gds-display-m > span.message-text on the live
   build, solid text (no gradient there to preserve). Pixel face, gold, the
   classic hard shadow. Scoped to the h1 so any suggestion chips below keep
   the UI face. clamp: Press Start is fixed-width and the line length varies
   with the wording and the user's name. */
__YUME_ROOT__ modular-zero-state h1,
__YUME_ROOT__ modular-zero-state h1 *,
__YUME_ROOT__ .zero-state-container h1,
__YUME_ROOT__ .zero-state-container h1 * {
  font-family: var(--ff-pixel) !important;
  font-size: clamp(0.95rem, 2.2vw, 1.35rem) !important;
  line-height: 1.7 !important;
  letter-spacing: 0.02em;
  color: var(--ff-gold) !important;
  -webkit-text-fill-color: var(--ff-gold) !important;
  background: none !important;
  text-shadow: 2px 2px 0 rgba(3, 6, 22, 0.85);
}

/* The composer placeholder ("Ask Gemini"). Quill draws it as a ::before on
   the empty editor. */
__YUME_ROOT__ rich-textarea .ql-editor.ql-blank::before {
  color: #a9b7e8 !important;
  opacity: 1;
  font-family: var(--ff-body) !important;
  font-size: 0.75rem !important;
}

/* The tiny print under the composer ("Gemini is AI and can make mistakes"). */
__YUME_ROOT__ hallucination-disclaimer,
__YUME_ROOT__ hallucination-disclaimer * {
  font-family: var(--ff-pixel-ui) !important;
  color: #8fa0d8 !important;
}

/* ---------------------------------------------------------- menu windows */

