  border: 0 !important;
  box-shadow: none !important;
}

__YUME_ROOT__ .mat-mdc-menu-item:hover,
__YUME_ROOT__ .mat-mdc-option:hover,
__YUME_ROOT__ .mat-mdc-menu-item.mat-mdc-menu-item-highlighted,
