/* The composer's + menu ("Upload and tools"), its More-uploads/More-tools
   flyouts, and any other lm-menu Material card in the overlay: these are
   mat-cards (bg #1f1f1f, radius 20px stock), not mat-menu panels, so they
   get their window dressing here. Scoped to the menu-flavoured cards so a
   future genuine content card isn't framed by accident. */
__YUME_ROOT__ .cdk-overlay-container mat-card.lm-menu-theme,
__YUME_ROOT__ .cdk-overlay-container mat-card[class*="card-container"],
__YUME_ROOT__ body mat-card.lm-menu-theme.card-container,
__YUME_ROOT__ mat-card.lm-menu-theme {
  /* The stock #1f1f1f fill is a literal, high-specificity declaration in a
