     here in full battle dress — the shorthand alone lost to it live. */
  background: var(--ff-window) !important;
  background-color: var(--ff-win-mid) !important;
  background-image: linear-gradient(180deg, var(--ff-win-top) 0%, var(--ff-win-mid) 58%, var(--ff-win-bot) 100%) !important;
  border: 2px solid var(--ff-frame) !important;
  border-radius: 7px !important;
  box-shadow: var(--ff-frame-shadow) !important;
  color: #fff !important;
}

__YUME_ROOT__ .cdk-overlay-container mat-action-list {
  background: transparent !important;
}

__YUME_ROOT__ .cdk-overlay-container button.lm-menu-item-theme,
__YUME_ROOT__ .cdk-overlay-container mat-action-list button {
