   data-yume-menu gets the pixel face except the icon ligatures. */
__YUME_ROOT__ .cdk-overlay-container button.lm-menu-item-theme .menu-text,
__YUME_ROOT__ .cdk-overlay-container button.lm-menu-item-theme .item,
__YUME_ROOT__ .cdk-overlay-container button.lm-menu-item-theme span:not(.mat-mdc-button-persistent-ripple),
__YUME_ROOT__ .cdk-overlay-container mat-action-list button span:not(.mat-mdc-button-persistent-ripple),
__YUME_ROOT__ mat-card[data-yume-menu] span:not(.mat-mdc-button-persistent-ripple):not([class*="lumi"]),
__YUME_ROOT__ mat-card[data-yume-menu] button:not([class*="lumi"]),
__YUME_ROOT__ mat-card[data-yume-menu] .mdc-list-item__primary-text {
  font-family: var(--ff-pixel-ui) !important;
  color: #fff !important;
  font-size: 12px !important;
}

__YUME_ROOT__ mat-card[data-yume-menu] mat-icon {
