__YUME_ROOT__ .mdc-tooltip__surface,
__YUME_ROOT__ .mat-mdc-tooltip-surface,
__YUME_ROOT__ .mdc-tooltip.gem-tooltip,
__YUME_ROOT__ mat-tooltip-component .mdc-tooltip {
