}

/* Chips (the notebook "N sources" pill and friends): little blue menu
   buttons, keyline and all. */
__YUME_ROOT__ mat-chip,
__YUME_ROOT__ mat-chip .mdc-evolution-chip__action,
__YUME_ROOT__ [class*="source-chip"],
__YUME_ROOT__ button[class*="sources-button"],
