}

/* ------------------------------------------------------- reply windows */

/* content.js stamps data-yume-reply on <model-response> once the reply holds
   real text (thoughts excluded), and data-yume-latest on the newest — same
   contract as the other sites. The frame wraps the response content, not the
   whole turn, so the action row below stays outside the window. */
__YUME_ROOT__ model-response[data-yume-reply] .response-container-content {
  background: var(--ff-window-reply) !important;
  border: 2px solid var(--ff-frame) !important;
  border-radius: 7px !important;
  box-shadow: var(--ff-frame-shadow);
  padding: 10px 14px 10px 40px !important;
  position: relative;
}

/* Crystal in the window's left gutter — the speaker mark. Width derives from
   the ripped asset's own aspect so a re-rip never squashes it. */
@keyframes ff-crystal-pulse {
  0%, 100% {
    filter: drop-shadow(0 0 4px rgba(120, 220, 255, 0.55)) brightness(1);
    transform: translateY(0);
  }
  50% {
    filter: drop-shadow(0 0 11px rgba(150, 235, 255, 0.95)) brightness(1.15);
    transform: translateY(-2px);
  }
}

__YUME_ROOT__ model-response[data-yume-reply] .response-container-content::before {
  content: "";
  position: absolute;
  left: 10px;
  top: 12px;
  height: 32px;
  width: calc(32px * var(--yume-ff-crystal-w) / var(--yume-ff-crystal-h));
  background: var(--yume-ff-crystal) center / contain no-repeat;
  image-rendering: pixelated;
  animation: ff-crystal-pulse 3.4s ease-in-out infinite;
  pointer-events: none;
  z-index: 1;
}

@media (max-width: 900px) {
  __YUME_ROOT__ model-response[data-yume-reply] .response-container-content { padding-left: 14px !important; }
  __YUME_ROOT__ model-response[data-yume-reply] .response-container-content::before { display: none; }
}

/* The newest reply breathes. */
@keyframes ff-reply-breathe {
  0%, 100% {
    box-shadow:
      inset 0 0 0 1px var(--ff-bevel),
      0 0 12px 1px rgba(92, 152, 255, 0.28),
      0 3px 0 var(--ff-drop);
  }
  50% {
    box-shadow:
      inset 0 0 0 1px rgba(196, 220, 255, 0.7),
      0 0 26px 5px rgba(134, 202, 255, 0.5),
      0 3px 0 var(--ff-drop);
  }
}

__YUME_ROOT__ model-response[data-yume-latest][data-yume-reply] .response-container-content {
  animation: ff-reply-breathe 4.2s ease-in-out infinite;
}

/* Gemini's transient "Thinking…" banner, mounted below the newest turn
   while the model reasons. A small menu window, indented past Mog's post so
   he reads as its herald rather than its obstruction. */
__YUME_ROOT__ .thinking-banner {
  display: inline-flex !important;
  align-items: center;
  margin-left: 40px !important;
  margin-top: 4px;
  padding: 4px 10px !important;
  background: var(--ff-window) !important;
  border: 2px solid var(--ff-frame) !important;
  border-radius: 6px !important;
  box-shadow: 0 2px 0 var(--ff-drop) !important;
  font-family: var(--ff-pixel-ui) !important;
