}

/* The pre-text skeleton shimmer, re-tinted to the window palette. */
__YUME_ROOT__ .skeleton-loader-container,
__YUME_ROOT__ .skeleton-loader-container * {
  background-color: rgba(47, 71, 168, 0.3) !important;
}

/* The thoughts drawer ("Show thinking") inside a reply: a quieter inset
   panel, like a scroll tucked into the window. */
__YUME_ROOT__ model-thoughts:not(:empty),
__YUME_ROOT__ thinking-overlay:not(:empty),
__YUME_ROOT__ .thoughts-container {
  background: rgba(4, 8, 30, 0.45) !important;
  border: 1px solid rgba(150, 180, 255, 0.25) !important;
  border-radius: 5px !important;
}
__YUME_ROOT__ .thoughts-content {
  background: transparent !important;
}

/* Code blocks lift off the window fill instead of blurring into it. */
__YUME_ROOT__ .markdown pre,
