}

/* The footer's settings gear becomes the menu crystal, as on the other two
   sites' profile rows. Width derives from the asset's own aspect so a
   re-rip never squashes it; the glyph hides by colour — the slot's size is
   load-bearing. */
__YUME_ROOT__ sidenav-mavatar-footer gem-icon-button mat-icon,
__YUME_ROOT__ [data-test-id="mavatar-footer-settings-button"] mat-icon {
  position: relative;
  color: transparent !important;
}
__YUME_ROOT__ sidenav-mavatar-footer gem-icon-button mat-icon::after,
__YUME_ROOT__ [data-test-id="mavatar-footer-settings-button"] mat-icon::after {
  content: "";
  position: absolute;
  inset: 0;
  margin: auto;
  height: 22px;
  width: calc(22px * var(--yume-ff-menu-crystal-w) / var(--yume-ff-menu-crystal-h));
  background: var(--yume-ff-menu-crystal) center / contain no-repeat;
  image-rendering: pixelated;
  pointer-events: none;
  filter: drop-shadow(0 0 4px rgba(139, 234, 255, 0.45));
}

/* ---------------------------------------------------------------- header */

/* The top bar: wordmark + actions float on the sky; chips get glass. */
__YUME_ROOT__ top-bar-actions,
__YUME_ROOT__ .top-bar-actions {
  background: transparent !important;
}

__YUME_ROOT__ top-bar-actions button,
__YUME_ROOT__ top-bar-actions gem-button {
  font-family: var(--ff-pixel-ui) !important;
}

__YUME_ROOT__ top-bar-actions button:hover,
__YUME_ROOT__ top-bar-actions button:hover mat-icon {
  color: var(--ff-gold) !important;
}

/* ---------------------------------------------------------------- buttons */

/* Filled/tonal Material buttons as the gold and blue menu buttons. */
__YUME_ROOT__ .mdc-button--unelevated,
__YUME_ROOT__ .mat-mdc-unelevated-button,
__YUME_ROOT__ .mat-primary.mat-mdc-raised-button {
  background: linear-gradient(180deg, #ffe58f 0%, #ffd75e 55%, #e2b83a 100%) !important;
  color: #241c04 !important;
  border: 2px solid #fff !important;
  border-radius: 5px !important;
  box-shadow: 0 2px 0 var(--ff-drop) !important;
  font-family: var(--ff-pixel-ui) !important;
}

__YUME_ROOT__ .mat-mdc-outlined-button,
__YUME_ROOT__ .mdc-button--outlined {
  background: linear-gradient(180deg, rgba(84, 114, 214, 0.55), rgba(18, 30, 92, 0.55)) !important;
  color: #fff !important;
  border: 1px solid rgba(255, 255, 255, 0.55) !important;
  border-radius: 5px !important;
  box-shadow: 0 2px 0 var(--ff-drop) !important;
  font-family: var(--ff-pixel-ui) !important;
}

__YUME_ROOT__ .mdc-button--unelevated:hover,
__YUME_ROOT__ .mat-mdc-unelevated-button:hover,
__YUME_ROOT__ .mat-mdc-outlined-button:hover {
  filter: brightness(1.12);
}

/* Focus ring in gold, matching the other sites' controls. */
__YUME_ROOT__ button:focus-visible,
__YUME_ROOT__ a:focus-visible {
  outline: 2px solid var(--ff-gold) !important;
  outline-offset: 2px !important;
}

__YUME_ROOT__ rich-textarea .ql-editor:focus,
__YUME_ROOT__ rich-textarea .ql-editor:focus-visible {
  outline: none !important;
}

/* Scrollbar as a menu slider: white rail, gold thumb. Inside the composer
   pill the editor's own scroller must NOT wear it — a 9px gold thumb next
   to the caret read as a mystery gold block — so the pill hides its
   scrollbars entirely, like Gemini's own UI does. */
__YUME_ROOT__ input-area-v2 ::-webkit-scrollbar,
__YUME_ROOT__ rich-textarea ::-webkit-scrollbar {
  width: 0 !important;
  height: 0 !important;
  display: none;
}
__YUME_ROOT__ rich-textarea .ql-editor {
  scrollbar-width: none;
}
__YUME_ROOT__ ::-webkit-scrollbar { width: 9px; height: 9px; }
__YUME_ROOT__ ::-webkit-scrollbar-thumb {
  background: var(--ff-gold) !important;
  border-radius: 2px !important;
  box-shadow: inset 0 0 0 1px rgba(3, 6, 22, 0.5);
}
__YUME_ROOT__ ::-webkit-scrollbar-track {
  background: rgba(255, 255, 255, 0.06) !important;
}

/* ------------------------------------------- optional: colourful text */

/* Gated on the per-theme toggle (popup ⚙ → data-yume-opt). Gold emphasis,
   cyan italics, magenta headings, green inline code, gold list markers. */
__YUME_ROOT__[data-yume-opt~="rich-text"] .markdown strong,
__YUME_ROOT__[data-yume-opt~="rich-text"] .markdown b {
  color: var(--ff-gold) !important;
  text-shadow: 1px 1px 0 rgba(3, 6, 22, 0.8);
}

__YUME_ROOT__[data-yume-opt~="rich-text"] .markdown em,
__YUME_ROOT__[data-yume-opt~="rich-text"] .markdown i {
  color: var(--ff-crystal-cyan) !important;
  font-style: italic !important;
}

__YUME_ROOT__[data-yume-opt~="rich-text"] .markdown h1,
__YUME_ROOT__[data-yume-opt~="rich-text"] .markdown h2,
__YUME_ROOT__[data-yume-opt~="rich-text"] .markdown h3,
__YUME_ROOT__[data-yume-opt~="rich-text"] .markdown h4 {
  color: #ff8ad8 !important;
  text-shadow: 1px 1px 0 rgba(3, 6, 22, 0.85);
}

__YUME_ROOT__[data-yume-opt~="rich-text"] .markdown code:not(pre code) {
  color: #7ce8a4 !important;
}

__YUME_ROOT__[data-yume-opt~="rich-text"] .markdown a {
  color: #9db4ff !important;
  text-decoration-color: rgba(157, 180, 255, 0.5) !important;
}

__YUME_ROOT__[data-yume-opt~="rich-text"] .markdown li::marker {
  color: var(--ff-gold) !important;
}

/* -------------------------------------------------------------- chocobo */

@keyframes ff-choco-gait {
  0%, 49.99% { background-position-x: 0%; }
  50%, 100%  { background-position-x: 100%; }
}

__YUME_ROOT__ .yume-choco {
  position: absolute;
  width: calc(var(--yume-ff-choco-w) * 2px);
  height: calc(var(--yume-ff-choco-h) * 2px);
  background-image: var(--yume-ff-choco);
  background-size: 200% 100%;
  background-repeat: no-repeat;
  image-rendering: pixelated;
  pointer-events: none;
}

/* Variant A — the parkour. Trajectory measured and driven by content.js via
   WAAPI; these wrappers only set the stage. Box bird crosses at z 39, one
   layer behind the party (40). */
__YUME_ROOT__ .yume-choco-a {
  position: absolute;
  left: 0;
  top: 0;
  width: calc(var(--yume-ff-choco-w) * 2px);
  height: calc(var(--yume-ff-choco-h) * 2px);
  z-index: 39;
  pointer-events: none;
  will-change: transform;
  filter: drop-shadow(0 2px 0 rgba(3, 6, 22, 0.5));
}

__YUME_ROOT__ .yume-choco-a .yume-choco,
__YUME_ROOT__ .yume-choco-sky .yume-choco {
  position: absolute;
  inset: 0;
  transform: scaleX(-1);
  animation: ff-choco-gait 0.22s steps(1) infinite;
}

/* Ground + leap segments: fixed on <body>, immune to ancestor clipping,
   one notch under the starfields. */
__YUME_ROOT__ .yume-choco-sky {
  position: fixed;
  left: 0;
  top: 0;
  width: calc(var(--yume-ff-choco-w) * 2px);
  height: calc(var(--yume-ff-choco-h) * 2px);
  z-index: 2147483643;
  pointer-events: none;
  will-change: transform;
  filter: drop-shadow(0 2px 0 rgba(3, 6, 22, 0.5));
}

/* Variants B/C — behind the composer's text, revealed edge-first. content.js
   mounts the clip on the composer host; the pill's z-index:0 (granted above)
   makes the z:-1 wrapper paint above the window fill, under the text. */
__YUME_ROOT__ .yume-choco-clip {
  position: absolute;
  top: 3px;
  left: 8px;
  right: 8px;
  height: calc(var(--yume-ff-choco-h) * 2px);
  overflow: hidden;
  pointer-events: none;
  z-index: -1;
}

@keyframes ff-choco-run-b {
  from { transform: translateX(var(--choco-dist, 800px)); }
  to   { transform: translateX(calc(var(--yume-ff-choco-w) * -2px)); }
}
@keyframes ff-choco-run-c {
  from { transform: translateX(calc(var(--yume-ff-choco-w) * -2px)) scaleX(-1); }
  to   { transform: translateX(var(--choco-dist, 800px)) scaleX(-1); }
}

__YUME_ROOT__ .yume-choco-b {
  animation:
    ff-choco-gait 0.22s steps(1) infinite,
    ff-choco-run-b var(--choco-dur, 4.2s) linear forwards;
}
__YUME_ROOT__ .yume-choco-c {
  animation:
    ff-choco-gait 0.22s steps(1) infinite,
    ff-choco-run-c var(--choco-dur, 4.2s) linear forwards;
}

/* --------------------------------------------------------------- motion */

@media (prefers-reduced-motion: reduce) {
  __YUME_ROOT__::before,
  __YUME_ROOT__::after,
  __YUME_ROOT__ body::before,
  __YUME_ROOT__ body::after,
  __YUME_ROOT__ fieldset.input-area-container,
  __YUME_ROOT__ input-container .input-area-container,
  __YUME_ROOT__ model-response[data-yume-latest][data-yume-reply] .response-container-content,
  __YUME_ROOT__ model-response[data-yume-reply] .response-container-content::before,
  __YUME_ROOT__ .yume-party-member,
  __YUME_ROOT__ .yume-shooting-star,
  __YUME_ROOT__ model-response[data-yume-working] .response-container::after,
  __YUME_ROOT__ side-navigation-content a:not([href^="http"]):hover::before,
  __YUME_ROOT__ side-navigation-content a.gem-nav-list-item.is-active,
  __YUME_ROOT__ side-navigation-content a.gem-nav-list-item[aria-current="page"] {
    animation: none !important;
  }
  __YUME_ROOT__ .yume-choco,
  __YUME_ROOT__ .yume-choco-clip,
  __YUME_ROOT__ .yume-choco-sky {
    display: none;
  }
}
